  group('l10n accessor sweep - every accessor is non-empty', () {
    test('en: every accessor returns a non-empty string', () {
      final empty = <String>[];
      accessors.forEach((name, read) {
        if (read(en).trim().isEmpty) empty.add(name);
      });
      expect(empty, isEmpty, reason: 'empty en: ${empty.join(', ')}');
    });

    test('ar: every accessor returns a non-empty string', () {
      final empty = <String>[];
      accessors.forEach((name, read) {
        if (read(ar).trim().isEmpty) empty.add(name);
      });
      expect(empty, isEmpty, reason: 'empty ar: ${empty.join(', ')}');
    });

    test('the sweep really reads every generated accessor', () {
      expect(accessors.length, 672);
    });
  });

  group('l10n leak detector - no Arabic value is silently English', () {
    test('only the language-neutral allowlist may share an en/ar value', () {
      final same = <String>[];
      staticAccessors.forEach((name, read) {
        if (read(en) == read(ar)) same.add(name);
      });
      expect(
        same..sort(),
        kLanguageNeutralValues.toList()..sort(),
        reason:
            'an accessor shares its en/ar value without being on the'
            ' allowlist - add the Arabic translation, or (only when the'
            ' value is truly language-neutral) extend the allowlist',
      );
    });
  });

